import{_ as s,o as a,c as i,ag as t}from"./chunks/framework.D1K3FKSn.js";const k=JSON.parse('{"title":"Resolution scaling & TAA","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kilnrender.com/rendering/resolution-taa.html"}],["meta",{"property":"og:title","content":"Resolution scaling & TAA | Kiln"}],["meta",{"property":"og:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}],["meta",{"property":"og:url","content":"https://kilnrender.com/rendering/resolution-taa.html"}],["meta",{"name":"twitter:title","content":"Resolution scaling & TAA | Kiln"}],["meta",{"name":"twitter:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}]]},"headers":[],"relativePath":"rendering/resolution-taa.md","filePath":"rendering/resolution-taa.md"}'),n={name:"rendering/resolution-taa.md"};function r(l,e,o,h,p,d){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="resolution-scaling-taa" tabindex="-1">Resolution scaling &amp; TAA <a class="header-anchor" href="#resolution-scaling-taa" aria-label="Permalink to &quot;Resolution scaling &amp; TAA&quot;">​</a></h1><h2 id="resolution-scaling" tabindex="-1">Resolution scaling <a class="header-anchor" href="#resolution-scaling" aria-label="Permalink to &quot;Resolution scaling&quot;">​</a></h2><p>The compute shader can render at a reduced resolution to decrease the number of rays cast per frame. A configurable <code>renderScale</code> factor (0.25-1.0, default 0.5) multiplies the canvas dimensions to produce a smaller compute output texture. The blit pass then upscales this to the full canvas using bilinear filtering.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Canvas: 1920 × 1080</span></span>
<span class="line"><span>renderScale: 0.5</span></span>
<span class="line"><span>Compute texture: 960 × 540  (75% fewer pixels)</span></span>
<span class="line"><span>Blit: bilinear upscale back to 1920 × 1080</span></span></code></pre></div><p>The depth texture remains at full resolution for geometry overlays (wireframe, axis). The scaled dimensions are passed into the shader as <code>screenSize</code> so that ray generation and thread dispatch use the correct coordinate space.</p><h2 id="temporal-jitter-and-accumulation" tabindex="-1">Temporal jitter and accumulation <a class="header-anchor" href="#temporal-jitter-and-accumulation" aria-label="Permalink to &quot;Temporal jitter and accumulation&quot;">​</a></h2><p>Raymarching with fixed step offsets produces banding artifacts where iso-surfaces align with sample planes. Kiln addresses this in two stages:</p><p><strong>Stochastic jitter</strong>: Each ray&#39;s starting offset is randomized per frame using the frame index as part of the seed:</p><div class="language-wgsl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">wgsl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> jitter </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rand</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rayToSeed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(rayDir) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> brickIter </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> uniforms</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">frameIndex);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> jitter </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stepSize;</span></span></code></pre></div><p>This converts structured banding into high-frequency noise that varies every frame.</p><p><strong>Temporal accumulation</strong>: A compute pass blends the current frame with a history buffer using an exponential moving average (EMA). Two ping-pong textures alternate as read and write targets to avoid read-write hazards:</p><div class="language-wgsl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">wgsl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> weight </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> /</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (frameCount </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // Progressive average</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> blended </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> mix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(history, current, weight);</span></span></code></pre></div><p>On frame 0, <code>weight = 1.0</code> shows the raw noisy frame. By frame 10, each pixel averages 11 samples, substantially reducing noise. Accumulation caps at 64 frames to avoid diminishing returns.</p><p>The accumulation resets automatically when:</p><ul><li>The camera moves (detected by comparing the view-projection matrix between frames)</li><li>Rendering parameters change (render mode, transfer function, window/level, ISO threshold)</li></ul><p>This gives immediate visual feedback during interaction, with progressive refinement when the view is still.</p>`,16)])])}const g=s(n,[["render",r]]);export{k as __pageData,g as default};
